export class WebExecutionProvider { async run(project,onLine){const start=performance.now(), html=project.files.find(f=>f.path==='index.html')?.content;if(!html)throw Error('No index.html found. Web preview requires an HTML entry point.');onLine('stdout','Preview built successfully.');return {status:'completed',exitCode:0,duration:performance.now()-start,html:this.bundle(project,html)}} bundle(project,html){return html.replace(/(?:src|href)=["']([^"']+)["']/g,(match,path)=>{const f=project.files.find(x=>x.path===path.replace(/^\.\//,''));if(!f)return match;if(path.endsWith('.css'))return `<style>${f.content}</style>`;if(path.endsWith('.js'))return `<script>${f.content}</script>`;return match})}}
export class SandboxExecutionProvider {async run(project,onLine){const f=project.files.find(x=>/\.(py|kt|ts|tsx|jsx)$/.test(x.path));throw Error(`${f?.path?.split('.').pop().toUpperCase()||'This'} runtime is not available in this browser. Use a remote sandbox provider to execute it.`)}}
export class ExecutionService {constructor(){this.web=new WebExecutionProvider();this.sandbox=new SandboxExecutionProvider()} async run(project,onLine){return project.files.some(f=>f.path==='index.html')?this.web.run(project,onLine):this.sandbox.run(project,onLine)}}
